<template>
  <div class="settings-page">
    <header><router-link to="/" class="brand">MIROFISHPLUS</router-link><router-link to="/">返回首页 ↗</router-link></header>
    <main>
      <div class="heading"><div><p>SETTINGS / CONFIGURATION CENTER</p><h1>配置中心</h1></div><button :disabled="saving" @click="apply">应用配置</button></div>
      <div v-if="notice" class="notice" :data-error="noticeError">{{ notice }}</div>
      <section>
        <div class="section-title"><div><small>01</small><h2>知识图谱服务</h2></div><span>选择知识图谱的存储与检索方式</span></div>
        <div class="backend-options" role="radiogroup" aria-label="知识图谱服务模式">
          <button type="button" role="radio" :aria-checked="memory.backend === 'cloud'" :class="{ active: memory.backend === 'cloud' }" @click="selectMemoryBackend('cloud')"><strong>Zep Cloud</strong><span>托管图谱服务，只需提供 API Key</span></button>
          <button type="button" role="radio" :aria-checked="memory.backend === 'graphiti'" :class="{ active: memory.backend === 'graphiti' }" @click="selectMemoryBackend('graphiti')"><strong>自定义 Neo4j</strong><span>通过 Graphiti 连接你的 Neo4j 实例</span></button>
        </div>
        <div class="memory-form">
          <template v-if="memory.backend === 'cloud'">
            <label for="zep-api-key">Zep API Key<input id="zep-api-key" v-model="memory.zep_api_key" type="password" autocomplete="new-password" :placeholder="memory.zep_api_key_masked || '请输入 Zep API Key'" @input="memoryTested=false"><span>留空则继续使用已保存的密钥，密钥不会回显。</span></label>
          </template>
          <template v-else>
            <label for="neo4j-uri">Neo4j URI<input id="neo4j-uri" v-model.trim="memory.neo4j_uri" placeholder="bolt://host.docker.internal:7687" @input="memoryTested=false"><span>Docker 连接宿主机可使用 host.docker.internal。</span></label>
            <label for="neo4j-user">用户名<input id="neo4j-user" v-model.trim="memory.neo4j_user" autocomplete="username" @input="memoryTested=false"></label>
            <label for="neo4j-password">密码<input id="neo4j-password" v-model="memory.neo4j_password" type="password" autocomplete="new-password" :placeholder="memory.neo4j_password_masked || '请输入 Neo4j 密码'" @input="memoryTested=false"><span>留空则继续使用已保存的密码。</span></label>
          </template>
        </div>
        <div class="memory-actions"><button type="button" class="secondary-action" :disabled="memoryTesting || memorySaving" @click="testMemoryBackend">{{ memoryTesting ? '测试中…' : '测试连接' }}</button><button type="button" class="primary-action" :disabled="memorySaving || !memoryTested" @click="saveMemoryBackend">{{ memorySaving ? '应用中…' : '应用图谱配置' }}</button><span aria-live="polite">{{ memoryStatus }}</span></div>
      </section>
      <section>
        <div class="section-title"><div><small>02</small><h2>三个模型职责</h2></div><span>配置持久化到 SQLite，新任务使用新版本</span></div>
        <div class="role-grid">
          <article v-for="role in roles" :key="role.key">
            <div class="role-mark">{{ role.number }}</div><h3>{{ role.title }}</h3><p>{{ role.description }}</p>
            <label>Provider 连接<select v-model="draft[role.key].connection_id" @change="selectRoleConnection(role.key)"><option value="">请选择</option><option v-for="item in compatibleConnections(role.key)" :key="item.connection_id" :value="item.connection_id">{{ item.name }}</option></select></label>
            <label>接口协议<select v-model="draft[role.key].protocol" :disabled="!draft[role.key].connection_id" @change="selectRoleProtocol(role.key)"><option value="">请选择协议</option><option v-for="item in compatibleProtocols(role.key)" :key="item.protocol" :value="item.protocol">{{ protocolLabels[item.protocol] }}</option></select></label>
            <label>模型名称<div class="model-select-row"><input v-if="modelStates[role.key].manualEntry" v-model.trim="draft[role.key].model" placeholder="请输入模型名称" @change="selectRoleModel(role.key)"><select v-else v-model="draft[role.key].model" :disabled="modelStates[role.key].loading || !draft[role.key].connection_id" @change="selectRoleModel(role.key)"><option value="">{{ modelStates[role.key].loading ? '正在加载模型…' : '请选择模型' }}</option><option v-if="draft[role.key].model && !modelStates[role.key].models.some(item=>item.id===draft[role.key].model)" :value="draft[role.key].model">{{ draft[role.key].model }}（当前配置）</option><option v-for="model in modelStates[role.key].models" :key="model.id" :value="model.id">{{ model.id }} · {{ model.capability === 'embedding' ? 'Embedding' : '文本' }}</option></select><button type="button" :disabled="modelStates[role.key].loading || !draft[role.key].connection_id" @click="refreshModels(role.key)">刷新</button></div><span v-if="modelStates[role.key].manualEntry">该服务不支持模型列表，请手工填写。</span><span v-if="modelStates[role.key].error" class="field-error">{{ modelStates[role.key].error }}</span></label>
            <details><summary>高级参数</summary><div class="advanced"><label v-if="role.key === 'embedding'">向量维度<input v-model.number="draft[role.key].dimensions" type="number" min="1"></label><label v-else>最大上下文 Tokens<input v-model.number="draft[role.key].context_window_tokens" type="number" min="1" required @input="markContextManual(role.key)"><span v-if="draft[role.key].model && !draft[role.key].context_window_tokens" class="field-error">未知模型需要手工填写最大上下文。</span></label><label>超时（秒）<input v-model.number="draft[role.key].timeout" type="number" min="1"></label><label v-if="role.key !== 'embedding'">最大并发<input v-model.number="draft[role.key].max_concurrency" type="number" min="1"></label><label v-if="role.key === 'high_throughput'" class="check"><input v-model="draft[role.key].fallback_enabled" type="checkbox">失败时回退高能力模型</label></div></details>
          </article>
        </div>
        <button class="save-draft" :disabled="saving" @click="save">保存草稿</button>
      </section>
      <section>
        <div class="section-title"><div><small>03</small><h2>Provider 连接</h2></div><span>密钥保存后不可回读</span></div>
        <div class="connection-toolbar"><p>统一管理模型服务的厂商、协议和认证信息。</p><button ref="addConnectionTrigger" class="add-connection-trigger" type="button" @click="openConnectionModal">新增连接</button></div>
        <div class="connections"><article v-for="item in connections" :key="item.connection_id"><div><strong>{{ item.name }}</strong><span>{{ providerLabel(item.vendor) }} · {{ item.protocols.map(row=>protocolLabels[row.protocol]).join(' / ') }}</span><code>{{ item.base_url }}</code></div><div><span>{{ item.api_key_masked || (item.auth_type === 'oauth_gateway' ? oauthAccountLabel : '无需密钥') }}</span><span v-if="testStates[item.connection_id]?.message" class="test-result" :data-status="testStates[item.connection_id].status" aria-live="polite">{{ testStates[item.connection_id].message }}</span><span v-if="deleteStates[item.connection_id]?.message" class="test-result" data-status="failed" role="alert">{{ deleteStates[item.connection_id].message }}</span><button v-if="item.auth_type === 'oauth_gateway' && !oauthAccount.authenticated" @click="startOAuth">登录 ChatGPT</button><button v-if="item.auth_type === 'oauth_gateway' && oauthAccount.authenticated" @click="logoutOAuth">退出登录</button><button :disabled="testStates[item.connection_id]?.status === 'testing'" @click="testConnection(item)">{{ testStates[item.connection_id]?.status === 'testing' ? '测试中…' : '测试' }}</button><button :disabled="deleteStates[item.connection_id]?.status === 'deleting'" @click="removeConnection(item)">{{ deleteStates[item.connection_id]?.status === 'deleting' ? '删除中…' : '删除' }}</button></div><div v-if="item.auth_type === 'oauth_gateway' && oauthLogin.status === 'waiting'" class="oauth-panel"><strong>授权 ChatGPT</strong><span>代码：<code>{{ oauthLogin.user_code }}</code></span><button @click="copyOAuthCode">复制代码</button><a :href="oauthLogin.verification_uri" target="_blank" rel="noopener">打开授权页面 ↗</a><span>等待授权…</span></div></article></div>
      </section>
    </main>
    <Teleport to="body">
      <div v-if="connectionModalOpen" class="modal-backdrop" @click.self="closeConnectionModal" @keydown.esc="closeConnectionModal">
        <section class="connection-modal" role="dialog" aria-modal="true" aria-labelledby="connection-dialog-title">
          <div class="modal-header"><div><small>PROVIDER CONNECTION</small><h2 id="connection-dialog-title">新增连接</h2></div><button type="button" aria-label="关闭新增连接弹窗" :disabled="connectionSubmitting" @click="closeConnectionModal">×</button></div>
          <form class="connection-form" @submit.prevent="addConnection">
            <label for="connection-name">连接名称<input id="connection-name" ref="connectionNameInput" v-model.trim="newConnection.name" required placeholder="例如：生产环境 OpenAI"></label>
            <div class="connection-form-grid two-columns">
              <label for="connection-vendor">厂商或接入方式<select id="connection-vendor" v-model="newConnection.vendor" @change="selectVendor"><option v-for="item in providerCatalog" :key="item.vendor" :value="item.vendor">{{ item.label }}</option></select></label>
              <label for="connection-auth">认证方式<select id="connection-auth" v-model="newConnection.auth_type" :disabled="managedOAuthProvider" @change="invalidateProtocolDetection"><option value="api_key">API Key</option><option value="oauth_gateway">OAuth Gateway</option><option value="none">无需认证</option></select></label>
            </div>
            <label for="connection-base-url">Base URL<input id="connection-base-url" v-model.trim="newConnection.base_url" required :readonly="managedOAuthProvider" placeholder="https://api.example.com/v1" @input="invalidateProtocolDetection"><span v-if="managedOAuthProvider" class="field-help">OAuth Gateway 地址由系统管理，不可修改</span></label>
            <label v-if="newConnection.auth_type === 'api_key'" for="connection-api-key">API Key<input id="connection-api-key" v-model="newConnection.api_key" type="password" autocomplete="new-password" placeholder="输入 API Key" @input="invalidateProtocolDetection"></label>
            <fieldset class="protocol-capabilities"><legend>接口协议能力</legend><label v-for="item in connectionProtocolStates" :key="item.protocol" class="protocol-option"><input v-model="item.selected" type="checkbox" @change="correctProtocol(item)"><span><strong>{{ protocolLabels[item.protocol] }}</strong><small>{{ item.capability === 'embedding' ? 'Embedding' : '文本生成' }} · {{ verificationLabel(item) }}</small></span></label></fieldset>
            <label v-if="hasUntestedSelection" class="manual-ack"><input v-model="manualProtocolAcknowledged" type="checkbox">我确认手动启用尚未验证的协议</label>
            <p v-if="connectionModalError" class="modal-error" role="alert">{{ connectionModalError }}</p>
            <p v-if="connectionTestStatus" class="connection-test-status" :data-status="connectionTestPassed ? 'passed' : 'failed'" aria-live="polite">{{ connectionTestStatus }}</p>
            <div class="modal-actions"><button v-if="connectionTestRequired" type="button" class="secondary-action test-draft-action" :disabled="connectionTesting || connectionSubmitting" @click="testDraftConnection">{{ connectionTesting ? '探测中…' : '探测协议' }}</button><button type="button" class="secondary-action" :disabled="connectionSubmitting || connectionTesting" @click="closeConnectionModal">取消</button><button type="submit" class="primary-action" :disabled="connectionSubmitting || connectionTesting || !protocolSelectionReady">{{ connectionSubmitting ? '正在提交…' : (!protocolSelectionReady ? '请选择协议' : '新增连接') }}</button></div>
          </form>
        </section>
      </div>
    </Teleport>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { applyModelDraft, cancelChatGptLogin, createModelConnection, deleteModelConnection, getChatGptAccount, getChatGptLoginStatus, getConnectionModels, getMemoryBackend, getModelConnections, getModelDraft, getModelMetadata, getProviderCatalog, logoutChatGpt, saveMemoryBackend as saveMemoryBackendRequest, saveModelDraft, startChatGptLogin, testDraftModelConnection, testMemoryBackend as testMemoryBackendRequest, testModelConnection } from '../api/modelSettings'
const connections = ref([]), saving = ref(false), notice = ref(''), noticeError = ref(false)
const testStates = reactive({})
const deleteStates = reactive({})
const oauthAccount = reactive({authenticated:false,email:null,plan:null})
const oauthLogin = reactive({status:'idle',login_id:null,user_code:null,verification_uri:null})
const modelStates = reactive({embedding:{loading:false,models:[],manualEntry:false,error:''},high_capability:{loading:false,models:[],manualEntry:false,error:''},high_throughput:{loading:false,models:[],manualEntry:false,error:''}})
let oauthTimer = null
const oauthAccountLabel = computed(()=>oauthAccount.authenticated ? `${oauthAccount.email || '已登录'} · ${oauthAccount.plan || ''}` : '未登录')
const roles = [{key:'embedding',number:'01',title:'Embedding',description:'向量写入与语义检索'}, {key:'high_capability',number:'02',title:'高能力模型',description:'本体、人设、规划、报告与问答'}, {key:'high_throughput',number:'03',title:'高吞吐模型',description:'图谱抽取、正式模拟与记忆回写'}]
const draft = reactive({embedding:{connection_id:'',protocol:'',model:'',dimensions:384,timeout:60},high_capability:{connection_id:'',protocol:'',model:'',context_window_tokens:null,timeout:600,max_concurrency:2},high_throughput:{connection_id:'',protocol:'',model:'',context_window_tokens:null,timeout:600,max_concurrency:8,fallback_enabled:true}})
const contextOverrides = reactive({high_capability:{},high_throughput:{}})
const providerCatalog = ref([])
const newConnection = reactive({name:'',vendor:'openai',auth_type:'api_key',base_url:'https://api.openai.com/v1',api_key:''})
const connectionModalOpen = ref(false), connectionSubmitting = ref(false), connectionModalError = ref('')
const connectionTesting = ref(false), connectionTestPassed = ref(false), connectionTestStatus = ref('')
const connectionProtocolStates = ref([]), manualProtocolAcknowledged = ref(false)
const connectionNameInput = ref(null), addConnectionTrigger = ref(null)
const memory = reactive({backend:'cloud',zep_api_key:'',zep_api_key_masked:'',neo4j_uri:'bolt://host.docker.internal:7687',neo4j_user:'neo4j',neo4j_password:'',neo4j_password_masked:''})
const memoryTesting = ref(false), memorySaving = ref(false), memoryTested = ref(false), memoryStatus = ref('')
const selectedProvider = computed(()=>providerCatalog.value.find(item=>item.vendor===newConnection.vendor))
const managedOAuthProvider = computed(()=>selectedProvider.value?.default_auth_type==='oauth_gateway')
const connectionTestRequired = computed(()=>['api_key','none'].includes(newConnection.auth_type))
const selectedConnectionProtocols = computed(()=>connectionProtocolStates.value.filter(item=>item.selected))
const hasUntestedSelection = computed(()=>selectedConnectionProtocols.value.some(item=>item.verification_status!=='passed'))
const protocolSelectionReady = computed(()=>selectedConnectionProtocols.value.length>0&&(!hasUntestedSelection.value||manualProtocolAcknowledged.value))
const protocolLabels = {openai_responses:'OpenAI Responses',openai_chat_completions:'OpenAI Chat Completions',anthropic_messages:'Anthropic Messages',openai_embeddings:'OpenAI Embeddings'}
const compatibleConnections = role => connections.value.filter(item => item.protocols?.some(row=>row.capability===(role==='embedding'?'embedding':'text_generation')))
const compatibleProtocols = role => {const item=connections.value.find(value=>value.connection_id===draft[role].connection_id);const capability=role==='embedding'?'embedding':'text_generation';return item?.protocols?.filter(row=>row.capability===capability)||[]}
const providerLabel = vendor => providerCatalog.value.find(item=>item.vendor===vendor)?.label || vendor
const roleNames = {embedding:'Embedding',high_capability:'高能力模型',high_throughput:'高吞吐模型'}
const rolesUsingConnection = connectionId => Object.entries(draft).filter(([,config])=>config.connection_id===connectionId).map(([role])=>roleNames[role])
async function load(){ const [c,d,m,p]=await Promise.all([getModelConnections(),getModelDraft(),getMemoryBackend(),getProviderCatalog()]);connections.value=c.data||[];providerCatalog.value=p.data||[];Object.entries(d.data||{}).forEach(([key,value])=>{Object.assign(draft[key],value);if(key!=='embedding'&&value.model&&value.context_window_tokens)contextOverrides[key][value.model]=value.context_window_tokens});Object.assign(memory,m.data||{}) }
function initializeProtocolStates(){const item=selectedProvider.value;connectionProtocolStates.value=(item?.protocols||[]).map(protocol=>({protocol,capability:protocol==='openai_embeddings'?'embedding':'text_generation',source:'manual',verification_status:'untested',selected:item.default_auth_type==='oauth_gateway'}));manualProtocolAcknowledged.value=item?.default_auth_type==='oauth_gateway'}
function selectVendor(){const item=selectedProvider.value;if(!item)return;newConnection.auth_type=item.default_auth_type;newConnection.base_url=item.default_base_url;initializeProtocolStates();invalidateConnectionTest()}
async function openConnectionModal(){connectionModalError.value='';invalidateConnectionTest();initializeProtocolStates();connectionModalOpen.value=true;await nextTick();connectionNameInput.value?.focus()}
function closeConnectionModal(){if(connectionSubmitting.value||connectionTesting.value)return;connectionModalOpen.value=false;connectionModalError.value='';invalidateConnectionTest();nextTick(()=>addConnectionTrigger.value?.focus())}
function resetConnectionForm(){const item=providerCatalog.value[0];Object.assign(newConnection,{name:'',vendor:item?.vendor||'openai',auth_type:item?.default_auth_type||'api_key',base_url:item?.default_base_url||'https://api.openai.com/v1',api_key:''});initializeProtocolStates()}
function invalidateConnectionTest(){connectionTestPassed.value=false;connectionTestStatus.value='';manualProtocolAcknowledged.value=false}
function invalidateProtocolDetection(){initializeProtocolStates();invalidateConnectionTest()}
function correctProtocol(item){if(item.selected&&item.verification_status!=='passed'){item.source='manual';item.verification_status='untested'}manualProtocolAcknowledged.value=false}
const verificationLabel = item => item.verification_status==='passed'?'已探测':item.verification_status==='failed'?'探测失败':'未验证'
async function testDraftConnection(){connectionTesting.value=true;connectionModalError.value='';connectionTestStatus.value='';try{const result=await testDraftModelConnection({...newConnection});connectionProtocolStates.value=(result.data.protocols||[]).map(item=>({...item,selected:item.verification_status==='passed'}));connectionTestPassed.value=connectionProtocolStates.value.some(item=>item.selected);connectionTestStatus.value=connectionTestPassed.value?'协议探测完成':'未探测到可用协议'}catch(e){connectionTestPassed.value=false;connectionTestStatus.value=e.response?.data?.error||e.message||'协议探测失败'}finally{connectionTesting.value=false}}
function selectMemoryBackend(backend){memory.backend=backend;memoryTested.value=false;memoryStatus.value=''}
function memoryPayload(){return {backend:memory.backend,zep_api_key:memory.zep_api_key,neo4j_uri:memory.neo4j_uri,neo4j_user:memory.neo4j_user,neo4j_password:memory.neo4j_password}}
async function testMemoryBackend(){memoryTesting.value=true;memoryStatus.value='';try{const result=await testMemoryBackendRequest(memoryPayload());memoryTested.value=true;memoryStatus.value=`连接成功 · ${result.data.latency_ms}ms`;notice.value='知识图谱服务连接测试通过';noticeError.value=false}catch(e){memoryTested.value=false;memoryStatus.value=e.response?.data?.error||e.message||'连接测试失败';notice.value=memoryStatus.value;noticeError.value=true}finally{memoryTesting.value=false}}
async function saveMemoryBackend(){memorySaving.value=true;try{const result=await saveMemoryBackendRequest(memoryPayload());Object.assign(memory,result.data||{}, {zep_api_key:'',neo4j_password:''});memoryStatus.value='配置已应用并持久化';notice.value='知识图谱服务配置已应用';noticeError.value=false}catch(e){notice.value=e.response?.data?.error||e.message||'配置应用失败';noticeError.value=true}finally{memorySaving.value=false}}
async function refreshModels(role){const connectionId=draft[role].connection_id;const protocol=draft[role].protocol;if(!connectionId||!protocol){Object.assign(modelStates[role],{loading:false,models:[],manualEntry:false,error:''});return}modelStates[role].loading=true;modelStates[role].error='';try{const result=await getConnectionModels(connectionId,role,protocol);modelStates[role].models=result.data||[];modelStates[role].manualEntry=Boolean(result.manual_entry)}catch(e){modelStates[role].models=[];modelStates[role].manualEntry=true;modelStates[role].error=e.response?.data?.error||e.message||'模型列表加载失败'}finally{modelStates[role].loading=false}}
async function selectRoleConnection(role){draft[role].protocol='';draft[role].model='';if(role!=='embedding')draft[role].context_window_tokens=null;Object.assign(modelStates[role],{models:[],manualEntry:false,error:''})}
async function selectRoleProtocol(role){draft[role].model='';if(role!=='embedding')draft[role].context_window_tokens=null;await refreshModels(role)}
function markContextManual(role){const model=draft[role].model;if(model)contextOverrides[role][model]=draft[role].context_window_tokens}
async function selectRoleModel(role){if(role==='embedding')return;const model=draft[role].model;if(!model){draft[role].context_window_tokens=null;return}if(Object.prototype.hasOwnProperty.call(contextOverrides[role],model)){draft[role].context_window_tokens=contextOverrides[role][model];return}const result=await getModelMetadata(model);draft[role].context_window_tokens=result.data?.context_window_tokens??null}
async function save(){saving.value=true;try{await saveModelDraft(draft);notice.value='草稿已保存';noticeError.value=false}catch(e){notice.value=e.message;noticeError.value=true}finally{saving.value=false}}
async function apply(){saving.value=true;try{await saveModelDraft(draft);await applyModelDraft();notice.value='配置已应用，新任务将使用新版本';noticeError.value=false}catch(e){notice.value=e.message;noticeError.value=true}finally{saving.value=false}}
async function addConnection(){if(!protocolSelectionReady.value){connectionModalError.value='请至少选择一个协议，并确认未验证协议';return}connectionSubmitting.value=true;connectionModalError.value='';try{await createModelConnection({...newConnection,protocols:selectedConnectionProtocols.value.map(({selected,...item})=>item)});const connectionName=newConnection.name;resetConnectionForm();invalidateConnectionTest();connectionModalOpen.value=false;await load();notice.value=`连接“${connectionName}”已新增`;noticeError.value=false;await nextTick();addConnectionTrigger.value?.focus()}catch(e){connectionModalError.value=e.response?.data?.error||e.message||'新增连接失败'}finally{connectionSubmitting.value=false}}
async function removeConnection(item){const usedBy=rolesUsingConnection(item.connection_id);if(usedBy.length){deleteStates[item.connection_id]={status:'failed',message:`无法删除：正在被 ${usedBy.join('、')} 使用`};return}if(!window.confirm(`确定删除连接“${item.name}”吗？`))return;deleteStates[item.connection_id]={status:'deleting',message:''};try{await deleteModelConnection(item.connection_id);delete deleteStates[item.connection_id];notice.value=`${item.name} 已删除`;noticeError.value=false;await load()}catch(e){const message=e.response?.data?.error||e.message||'删除失败';deleteStates[item.connection_id]={status:'failed',message};notice.value=message;noticeError.value=true}}
async function testConnection(item){testStates[item.connection_id]={status:'testing',message:'正在测试连接…'};try{const result=await testModelConnection(item.connection_id);const message=`测试通过 · ${result.data.latency_ms}ms`;testStates[item.connection_id]={status:'passed',message};notice.value=`${item.name} ${message}`;noticeError.value=false}catch(e){testStates[item.connection_id]={status:'failed',message:'测试失败'};notice.value=e.message;noticeError.value=true}}
async function refreshOAuthAccount(){try{const result=await getChatGptAccount();Object.assign(oauthAccount,result.data||{})}catch{Object.assign(oauthAccount,{authenticated:false,email:null,plan:null})}}
async function startOAuth(){const result=await startChatGptLogin();Object.assign(oauthLogin,result.data);clearInterval(oauthTimer);oauthTimer=setInterval(pollOAuth,2000)}
async function pollOAuth(){if(!oauthLogin.login_id)return;const result=await getChatGptLoginStatus(oauthLogin.login_id);Object.assign(oauthLogin,result.data);if(oauthLogin.status!=='waiting'){clearInterval(oauthTimer);oauthTimer=null;if(oauthLogin.status==='authenticated'){await refreshOAuthAccount();notice.value='ChatGPT 登录成功';noticeError.value=false}else{notice.value=`ChatGPT 登录状态：${oauthLogin.status}`;noticeError.value=true}}}
async function copyOAuthCode(){await navigator.clipboard.writeText(oauthLogin.user_code);notice.value='授权代码已复制'}
async function logoutOAuth(){if(!window.confirm('确定退出 ChatGPT OAuth 登录吗？'))return;await logoutChatGpt();Object.assign(oauthAccount,{authenticated:false,email:null,plan:null});Object.assign(oauthLogin,{status:'idle',login_id:null,user_code:null,verification_uri:null})}
onMounted(async()=>{await Promise.all([load(),refreshOAuthAccount()])})
onBeforeUnmount(()=>{if(oauthTimer)clearInterval(oauthTimer)})
</script>

